(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,880790,e=>{"use strict";var i=e.i(843476),l=e.i(811337);function s(e){let s={li:"li",p:"p",strong:"strong",ul:"ul",...(0,l.useMDXComponents)(),...e.components},{AnketaCollapse:r,AnketaGroup:d,AnketaList:c,AnketaPoint:j,AnketaProse:x,MdxImage:h,Whisper:t}=s;return r||n("AnketaCollapse",!0),d||n("AnketaGroup",!0),c||n("AnketaList",!0),j||n("AnketaPoint",!0),x||n("AnketaProse",!0),h||n("MdxImage",!0),t||n("Whisper",!0),(0,i.jsxs)(d,{children:[(0,i.jsx)(r,{title:"Общая информация",defaultOpen:!0,children:(0,i.jsxs)(c,{children:[(0,i.jsxs)(j,{title:"Имя персонажа [русс|англ]",children:[(0,i.jsx)(s.p,{children:(0,i.jsx)(s.strong,{children:"Раймон Диас | Raymond Diaz"})}),(0,i.jsxs)(s.ul,{children:["\n",(0,i.jsx)(s.li,{children:"«Диас», «Рэй» — краткие формы имени, используемые близкими;"}),"\n",(0,i.jsxs)(s.li,{children:["В Энкраже можно услышать о нём как ",(0,i.jsx)(s.strong,{children:"«Чёрный Маркиз»"}),". Раймон предположил, что как-то раз он проговорился о том, как над ним потешались старые товарищи, и данное прозвище закрепилось."]}),"\n"]})]}),(0,i.jsx)(j,{title:"Возраст",children:(0,i.jsxs)(s.ul,{children:["\n",(0,i.jsx)(s.li,{children:"прожитый на земле: 43 года."}),"\n",(0,i.jsx)(s.li,{children:"дата рождения — 01.01.1545г. | смерти — 07.08.1588г."}),"\n",(0,i.jsx)(s.li,{children:"прожитый в Загробном мире как грешная душа: 430 лет"}),"\n"]})}),(0,i.jsx)(j,{title:"Пол",children:(0,i.jsx)(s.p,{children:"Мужской"})}),(0,i.jsxs)(j,{title:"Раса",children:[(0,i.jsx)(s.p,{children:"Ногицунэ."}),(0,i.jsxs)(s.ul,{children:["\n",(0,i.jsx)(s.li,{children:"При жизни Раймону удосужилось проявить себя как проницательного, хитрого и умного человека, который всячески стремился достичь не только своих целей, но и власти. Лисье коварство и обаяние ещё при жизни преследовали Раймона. В грешной жизни это проявилось лучше. Кроме того, особенно хорошо сыграло недоверие и ненависть к поставленным рамкам. Алчность, жадность и игры в маски — тоже родные качества. Сильным толчком на становлении ногицунэ стала преимущественно ещё и его жизнь в образе горделивого и алчного человека, что стремился заполучить власть и деньги после одного очень переломного для себя момента;"}),"\n",(0,i.jsx)(s.li,{children:"Раймон стал проявлением злобной стороны всех лисов — ногицунэ. Кроме того, он стал одним из тех редких исключений, когда хвост появляется каждые 50 лет. По этой причине Раймон стал одним из тех немногих лисов, у которых сейчас 9 хвостов."}),"\n"]})]})]})}),(0,i.jsxs)(r,{title:"Психологический профиль",children:[(0,i.jsx)(r,{title:"Характер",children:(0,i.jsxs)(x,{children:[(0,i.jsx)(s.p,{children:"Говоря о Раймоне Диасе, в первую очередь стоит знать об истории сына движения – когда-то он был частью непобедимой армады, одним из капитанов, чьё имя знали и уважали. Тогда он блистал дисциплиной, обладал властью, обязан был поражать скоростью принятых решений и брать на себя ответственность за людей. В те давние времена море даровало ему ощущение свободы, но именно погоня за ней и стала причиной его гибели – он отказался подчиняться тому, что считал оковами, и заплатил за это дорого. В то же время, смерть не стала для Раймона точкой, ведь загробная жизнь даровала ему новый шанс – не отказаться от себя, но измениться."}),(0,i.jsx)(s.p,{children:"Вслед за потерянной жизнью исчез и бывалый простор, в котором можно было бороздить моря. Справедливо ли то, что он обратился в ногицунэ, или же это насмешка жизни? Плевок, говорящий о том, что свобода была лишь прикрытием, попыткой сбежать от собственной алчной натуры испанского аристократа? Больше нельзя было брать курс, невозможно подчинять стихию, невозможно доказывать силу через риск и скорость – всё, что раньше решалось действием, теперь решается ожиданием, расчётом и участием в чужих играх. Раймон быстро понял, что прежние методы больше не работают, и неминуемо ему следует вернуться туда, откуда он с неохотой пытался сбежать – из душных кабинетов сначала отца, впоследствии засев у чёрного рынка, ступив в мир интриг."}),(0,i.jsx)(s.p,{children:"Раймон по-прежнему не доверяет окружающим и редко подпускает кого-либо близко, однако если раньше он давил и проверял людей на прочность, то теперь предпочитает наблюдать – ногицунэ стал внимательнее к деталям, осторожнее в словах, сдержаннее в реакциях – хотя долго считал подобное слабостью, ведущей к брожению. В некоторой степени его характер утратил резкость, но не жёсткость: Раймон перестал искать конфликты, однако не избегает их, если они оказываются неизбежны, но уже заранее обязывает себя иметь козыри в рукаве. Впрочем, он редко действует первым, предпочитая позволить ситуации раскрыться пёстрыми лепестками, прекратив тратить силы впустую и начав ценить стабильность. И хотя это может казаться неочевидным, в Раймоне всё ещё живёт стремление к свободе – оно ничуть не исчезло, но обратилось во внутреннее сопротивление навязанным правилам, как бы принимая их внешне, но не считая окончательными – вероятно, потому за ним наблюдается любовь подстраивать всё под себя и занимать те позиции, которые поддержат его. Да, Раймон до сих пор остаётся человеком, который ищет выходы, даже если внешне кажется смирившимся – он ищет обходные пути, альтернативные позиции и способы перехватить контроль, даже если внешне демонстрирует согласие."}),(0,i.jsx)(s.p,{children:"Отдельное место занимает манерность, унаследованная от воспитания и положения. Раймон вежлив, сдержан и зачастую подчеркнуто аккуратен в выражениях, даже в напряжённых ситуациях. Он внимательно следит за речью, жестами и тоном, считая самодисциплину необходимым условием выживания в среде интриг. Диас редко в том числе говорит прямо о своих намерениях и почти никогда не демонстрирует подлинное отношение к происходящему. Общительность, обаятельность и немного юмора стали способом добиться желаемого, а лёгкость в словах служит для соблюдения ревностно выстроенной дистанции после потерь и боли. Он умеет создать ощущение доверия, но сам при этом остаётся отстранённым, предпочитая наблюдать за реакциями и делать выводы, не раскрываясь полностью; он может казаться менее опасным, чем есть на самом деле, сознательно снижая ожидания окружающих. И чем более непринуждённым кажется его поведение, тем внимательнее он запоминает детали и лучше адаптируется под собеседника, дабы выстроить свой образ и исполнить задуманное."}),(0,i.jsx)(s.p,{children:"Он редко кого уважает искренне и почти никогда не идеализирует людей – каждый, с кем он имеет дело, рассматривается им как переменная в более обширной игре. Однако тех немногих, кого он признаёт равными по уму или полезности, Раймон изучает особенно внимательно, стараясь понять мотивы, слабости и пределы допустимого. Лояльность для него не является ценностью сама по себе — она имеет смысл только тогда, когда подкреплена взаимной выгодой."}),(0,i.jsx)(s.p,{children:"Алчность Раймона никуда не исчезла, но изменила форму… речь идёт не столько о деньгах (в Энкраже они ведь потеряли смысл), сколько о власти, информации и возможностях – он по-прежнему зависим от знания, стремится понимать устройство людей и систем, искать уязвимости и точки давления. Его интерес носит практический характер: его нельзя назвать коллекционером каких-нибудь безделушек, скорее уж человеком, который оценивает, какую пользу можно извлечь из полученного. Поминая о практичности, следует уточнить, что особую симпатию (даже навязчивую) в Раймоне вызывает наука, причём привлекать его стал не сам процесс исследования, сколько возможность выудить контроль над ранее неизведанным. Знания служат для него таким же ресурсом, способный дать преимущество, а потому Раймон стремится разбирать явления до основания. И хотя его любознательность лишена романтики — он изучает, чтобы понимать, и понимает, чтобы использовать, – в то же время, она не лишена эстетизма, но она носит сугубо избирательный характер. Раймон ценит не красоту как таковую, а упорядоченность, завершённость и ясность структуры – его привлекают чёткие закономерности, логические связи и моменты, в которых хаос уступает место контролю. Его в том числе не интересует жестокость, но он всецело готов к ней, если она выступает побочным продуктом проводимых исследований. При отсутствии возможностей он способен долго выжидать, накапливать теоретическую базу и искать обходные пути, не теряя интереса и не снижая планку требований к конечному результату."})]})}),(0,i.jsx)(r,{title:"Страхи",children:(0,i.jsxs)(c,{children:[(0,i.jsx)(j,{title:"Мизофобия",children:(0,i.jsx)(s.p,{children:"Раймон ненавидит, когда к нему прикасаются, ибо боится чем-то испачкаться и просто не любит чужой навязчивости (но это не говорит о том, что он сам не может быть таковым). Особенно со стороны женщин. Данный страх частично связан с его трагичным эпизодом с возлюбленной. Кроме того, учитывая, в какой грязи умер Раймон, конкретно в Энкраже он решил, что больше никому не даст так унизить себя. Да, он считает грешников «грязными и опасными» своей энергией, из-за чего и носит маску и уже очень давно не дышит. Раймон очень резко реагирует за любую попытку прикоснуться к нему, если только это не грешники, которых он «принимает» и не против сам касаться, однако «доверие» нужно заслужить."})}),(0,i.jsx)(j,{title:"Промывка мозгов",children:(0,i.jsx)(s.p,{children:"Он боится стать безжизненной и мертвой куклой, потерять себя и свою личность. По этой причине лис очень внимателен и трудно поддается иллюзиям, даже самым сильным."})}),(0,i.jsx)(j,{title:"Страх поддаться гневу",children:(0,i.jsx)(s.p,{children:"Раймон не любит совершать ошибки, пусть он на них и учится, но позволить выйти своим эмоциям наружу и сломать те образы, те маски, которые он создавал столько лет — никогда. Они стали с Раймоном одним целым, поэтому он без них попросту не знает как будет жить."})}),(0,i.jsx)(j,{title:"Клетки",children:(0,i.jsx)(s.p,{children:"Или иная форма заточения. Абсолютная ограниченность и чувство связанности, привязанности — всё это долгое время терзало Раймона, и он старался от этого сбежать. Всю свою жизнь Раймон путешествовал и обожал морские просторы, потому в заточении (особенно том, которое он не сам контролирует — то есть не он засел в кабинете, а его поймали) быть для него подобно психологической пытке. Конечно, он в себя обязательно придёт, но первые несколько секунд может даже запаниковать, если лишить его фактической свободы."})}),(0,i.jsx)(j,{title:"Страх живого пожирания",children:(0,i.jsx)(s.p,{children:"Боится всего, что связано с живым пожиранием. Следствие мизофобии. Проникновение насекомых под кожу, пожирание изнутри — очень мерзкое ощущение, о котором даже представлять тошно. Он боится самого того чувства, что паразит будет жрать его изнутри и что-то делать с его оболочкой. По этой причине остерегается всех, у кого есть подобные способности. С такими грешниками он особо осторожен и бдителен."})})]})}),(0,i.jsx)(r,{title:"Мечты, цели",children:(0,i.jsxs)(x,{children:[(0,i.jsx)(s.p,{children:"Одной из главных целей (именно целей!) Раймона считается изучить весь Энкраж. Он видит в нём перспективу и возможность, если исключить тот грех алчности ногицунэ, который в нём заседает."}),(0,i.jsx)(s.p,{children:"Ещё одной немаловажной целью является попытка найти Зло Всего Мира, к которому стремится его духовный брат."}),(0,i.jsx)(s.p,{children:"Не исключено, что Раймон хочет узнать, кто же такой Сталкер. Не ставит это конкретной и важной для себя целью, но она имеет место быть как мечта."}),(0,i.jsx)(s.p,{children:"Ну и в отдельную касту можно вынести, конечно, изучение природы Пустых, особенно легендарных — тоже считается целью, потому что Раймон уже принялся за их изучение, правда, начал пока что с низших."})]})}),(0,i.jsx)(r,{title:"Биография (при жизни)",children:(0,i.jsxs)(x,{children:[(0,i.jsx)(t,{children:(0,i.jsx)(s.p,{children:"Если бы у тебя было много времени на часах — что бы ты сделал? Наверное, я был бы тем, кто не позволил бы навредить своей семье, и никогда не отправился бы на эту битву"})}),(0,i.jsx)(s.p,{children:(0,i.jsx)(s.strong,{children:"Всё началось с Испании XVI века."})}),(0,i.jsx)(s.p,{children:"Зима 1545 года, земли Кастильской короны. Здесь был рождён тот, кто стал последним наследником семьи Диас по мужской линии. Отец его — Селио Диас, мать же носила имя Эрнестина."}),(0,i.jsx)(s.p,{children:"В истории юного Рэя не было несчастий всё его младенчество и детство: семья была довольно спокойной и любимой, хотя, сколько Раймон себя помнит, мать он практически никогда не видел и она даже не пыталась заботиться о нём, чего нельзя было сказать об отце. Тот, довольный рождением первого мужчины семейства, наконец-то был готов посвятить свою жизнь суше и открыть душу тому, кто станет наследником всего, чего он добился за свою славную жизнь. Раймон получал любовь и заботу, наставление и мудрость отца все свои эти и даже последующие годы, за что будет вспоминать отца с большой благодарностью."}),(0,i.jsx)(s.p,{children:"Начал получать образование Раймон в довольно раннем возрасте — и всё было из-за надежд и великого будущего Селио Диаса, мечтавшего привести свою династию в рассвет. Получал на тот момент Раймон образование на дому, как и подобает любому аристократу, начал получать необходимое образование как подобает будущему наследнику. Сам по себе юный Диас был довольно спокойным и очень смышленым ребёнком, а также, со временем, открыл в себе тайный интерес и любовь к путешествиям, к морям и океанам, любовь которую привил ему великий маркиз, рассказывая различные истории о пиратах и громких мореплавателях. Влюбившийся в эти истории Раймон ещё тогда решил, что эти мечты он хочет реализовать в жизни, и в будущем душа детская начнёт чахнуть от воодушевленной мечты сбежать из дома и отправиться в кругосветное путешествие, почувствовав солоноватый запах моря и вкус неизвестных опасностей."}),(0,i.jsx)(s.p,{children:"В 1550-му году, в возрасте пяти лет для Раймона, Диасы отправились в одно из тогдашних графств Норвегии с поздравлением горячо любимого дяди с рождением его первенца — в дальнейшем известному нам как Август Линдберг. Новое путешествие привело мальчика в восторг, отчего встреча запомнилась ему весьма надолго и ещё тогда глубоко засело в сердце. Хоть они приехали и с опозданием, однако графство Линдбергов устроило тогда весьма громкий банкет, на котором собралось не только всё семейство, но и близкие знакомые норвежской и испанской семей. Тогда Раймон впервые познакомился со своим маленьким кузеном, которого лелеяла вся семья без исключений. Мальчику было крайне необычно видеть создание даже меньше его по возрасту, однако он пропитался своей собственной братской любовью за всё то время, которое они успели провести вместе, чего в жизни у него уже никогда не будет."}),(0,i.jsx)(s.p,{children:"В промежутке между важными событиями таких годов как 1550 и 1552 Раймон учился читать довольно много книг, очень часто сидел дома и пользовался возможностью научиться чему-то новому. Особенно его продолжали захватывать истории, из-за чего тот откровенно сел на уши отцу с тем, что он хочет отправиться в плавание в своём юном возрасте. Ещё тогда, путешествуя по морю к своему кузену, он настолько впечатлился, что однажды закатил истерику, на которую умудрилась среагировать сама матушка. Она долго успокаивала плачущего Раймона, но не смогла найти к нему материнский подход — момент уже был упущен."}),(0,i.jsx)(s.p,{children:'1552 год стал впечатляющим для Раймона, ведь в этом году состоялось прибавление в семействе, однако ему, наверное, был открыто рад только сам ребёнок, нежели отец или мать. Конечно, младенца, коего назвали Эридой, они не обделяли вниманием, однако в проявлениях любви, которое могло было быть в понимании уже тогда 7-летнего Раймона, девочка была обделена. В этом же году и снова повторилась история: приехали родственники из графства уже германского (Август переехал спустя год благодаря браку своей сестры), снова случилось празднование, но, наверное, не такое пышное, как это произошло при рождении Раймона. Августу тогда уже было 2 года, и вместе они проводили довольно много времени и в этот приезд — его довольно часто оставляли со своими младшими, в то время как старшие занимались собственными делами. Точнее, как подслушал Раймон, решали важные "деловые" вопросы. Но детское любопытство знало границы хотя бы здесь, равно как и воспитание сказывалось на нём, из-за чего больше подобных происшествий он в своей жизни не допустит.'}),(0,i.jsx)(s.p,{children:"С возрастом Селио Диас становился жёстче, но это было во благо воспитания — любить Раймона он ни на секунду не прекращал. Тем не менее, он вынужден был согласиться тогда со своим братом о том, что парня придётся с возрастом приучивать к ответственности и выбивать детские мечты из головы. И хотя Селио не хотел лишать сына таких вещей, однако Раймон всё чаще и чаще получал отказы, получал наказания за попытки сбежать из дома, участившиеся особенно в подростковых годах 10-11 лет. Наверное единственным его утешением была только география и история, изучение которых хоть и ненамного, но компенсировало интерес блуждающей по морям души, пусть он и не прекращал попытки хоть как-то вырваться из гнезда и вкусить взрослой жизни. Раймону приходилось мириться с жестокими выговорами и даже принижением собственной мечты, выставляя её бесполезной в его положении, которую в нём когда-то поселил же и отец. Его интенсивнее нагружали науками и занятиями на улице, иногда доходило до бессонниц, из-за чего Раймон довольно часто прятался и пытался всегда оставаться в одиночестве. Спасение приходило лишь от внимания малютки-сестры Эриды, с которой он любил проводить время, и с которой никогда не проводили время родители. Это не была жалость от подростка, но была искренняя любовь к родному, что он хотел защитить. Возможно, именно поэтому он не решался предпринять серьёзной попытки для того, чтобы исполнить свою мечту. Терпел ради любимой сестры, которой тоже читал различные сказки и играл с большой охотой в свободное время. Нередко за ним числились даже прогулы занятий ради того, чтобы побыть с ней, и не выносил выговоров маркиза за то, что тот пытался их разлучить и поставить долг династии выше родной крови."}),(0,i.jsx)(s.p,{children:"Причиной отказов отца всё это время за карьеру, как понял уже подросший Раймон, заключалась в политической ситуации между чужеземными коронами. Однако что-то поменяло мнение отца и, кажется, он решил больше не противиться желанию Раймона и реализовать его мечту более грамотно. Юный Диас предполагает, что искренний и спокойный разговор с отцом сыграл на нём роль, но думает, что и дядя повлиял на решение в связи с военным положением. Детально с ситуацией он познакомился лишь тогда, когда отец пристроил его благодаря связям и влиянию семьи в Севилью на дворянское морское воспитание при Каса-де-Контратасьон — главном морском и навигационном доме Кастилии. Раз уж Раймон столь отчаянно стремился связать свою жизнь с морем, у Диаса почти не осталось выбора, кроме как позволить сыну пройти этот путь достойно. Там юношей благородного происхождения обучали навигации, морской астрономии, составлению карт, артиллерии и управлению судами короны. И как бы маркиз Селио ни противился происходящему, отказаться от собственного долга он тоже не мог. К 1561 году, находясь на службе короны и уже не впервые выходя в море под кастильскими знамёнами, он был вынужден вновь вернуться к командованию одной из морских эскадр. Испании приходилось собирать все возможные силы, и Селио до последнего откладывал как собственное возвращение на службу, так и отправление сына в Севилью. Но именно в тот момент, когда Раймона согласились принять благодаря заслугам и имени рода, выбора уже не осталось: навыки старого капитана не должны были пылиться без дела, а сыну предстояло научиться служить Испании иначе, чем служил его отец."}),(0,i.jsx)(s.p,{children:"Начались годы реализации маленькой мечты. Тем же часом, хоть и с большим трудом, но раз в год приплывали норвежские корабли и позволяли кузенам видеться друг с другом. Приплывали они довольно не часто из-за того, что на тот период на испанские корабли велась практически открытая охота со стороны Англии, Франции и Голландии, поэтому маркиз Селио отказывал в этом удовольствии. Тем не менее, даже редкие коммуникации не позволяли братьям прекратить своё общение, и смышленый уже тогда 14-летний Раймон развлекал своего 9-летнего брата и 7-летнюю сестру. Но ему нужно было идти на обучение."}),(0,i.jsx)(s.p,{children:"Свободного времени у Раймона почти не осталось с того самого дня, как он оказался среди молодых дворян, прибывших в Севилью со всех уголков Кастилии. Обучение при Каса-де-Контратасьон оказалось куда суровее, чем он представлял себе в юности: юношей поднимали ещё до рассвета, заставляли часами изучать карты, звёздные таблицы и морские расчёты, а ошибки на практических занятиях не прощались никому, вне зависимости от происхождения. И всё же Раймону это нравилось. Он чувствовал, что впервые по-настоящему приблизился к своей цели, а прежнее любопытство к морскому делу наконец находило применение. За эти годы он успел обзавестись полезными знакомствами как среди ровесников, так и среди старших воспитанников, что позднее сыграло важную роль в его положении при дворе и флоте, но самым значительным знакомством стала встреча с Полом Вагнером — юношей из графского рода. Они были одного возраста и почти сразу нашли общий язык. Во время занятий, морских практик и бесконечных тренировок их редко видели порознь."}),(0,i.jsx)(s.p,{children:"В течение нескольких лет Раймон постигал искусство навигации, ведение морских кампаний, основы фортификации и тактику морского боя под руководством опытных капитанов, космографов и людей, служивших короне не одно десятилетие. Позднее к теории прибавились и практические выходы в море. Обучение проходило в напряжённой обстановке: положение Испании требовало всё новых офицеров и мореходов, а потому молодых дворян готовили быстро и жёстко. Однако даже подобная строгость не могла погасить восторг Раймона: в его глазах всё ещё горел тот юношеский огонь человека, сумевшего прикоснуться к собственной мечте. Габриэль де Эстрада ничуть не уступал ему в стремлениях, и вместе они напоминали ветер и пламя, способные однажды разрастись в настоящую бурю. В том же году Раймон познакомился и с Рейесом де Валькасаром — вторым сыном герцогского дома кастильской короны, дружба с которым поначалу казалась почти невозможной. Они слишком по-разному смотрели как на службу, так и на саму жизнь: если Раймон видел в море прежде всего свободу, движение и возможность вырваться за пределы чужой власти, то Рейес относился к службе куда спокойнее и серьёзнее, воспринимая её скорее как долг перед семьёй, людьми и короной. Поначалу Раймона раздражала эта сдержанность — ему казалось, будто де Валькасар слишком правильный для человека их возраста: слишком терпеливый, слишком собранный, слишком привыкший сначала думать о последствиях, а уже потом действовать. Сам Рейес, в свою очередь, долгое время воспринимал Раймона человеком беспокойным и почти опасно увлекающимся собственными желаниями, словно тот постоянно искал возможность шагнуть за рамки. И всё же со временем различие характеров не оттолкнуло их друг от друга, а напротив — неожиданно сблизило: Раймон быстро понял, что за спокойствием Рейеса скрывается редкая надёжность, благодаря которой рядом с ним становилось легче даже в самые тяжёлые дни обучения. Рейес же постепенно начал видеть за внешней дерзостью Раймона человека удивительно живого, искреннего в своих стремлениях и неспособного мириться с клеткой, какой бы красивой она ни выглядела со стороны. Их дружба вытечет за рамки их обучения в Каса-де-Контратасьон и однажды столкнёт в трагичной судьбе одного из моряков…"}),(0,i.jsx)(s.p,{children:"Обучение завершилось в 1563 году с тем же горячим сердцем, с каким Раймон впервые переступил порог севильского дома морского воспитания. В честь выпуска молодых дворян и будущих офицеров в гавани устроили торжественный смотр кораблей, собравший множество придворных и представителей флота. Именно тогда Раймон впервые предстал перед светским обществом как человек, завершивший обучение на службе короне. Среди присутствующих находился и сам Филипп II, перед которым юноши приносили клятву верности. Лишь душа его помнит о том, как он тогда волновался, стоило ему увидеть короля Испании и его высшую свиту, о встрече с которыми он и представить себе во снах не мог. И лишь после этих событий Раймон возвращается домой, радостно встречая сестру в её 11-летние годы."}),(0,i.jsx)(s.p,{children:"Однако не смог надолго Раймон задержаться — военное положение обязывало пойти Раймона на службу."}),(0,i.jsx)(s.p,{children:"Первое официальное плавание Раймона, состоявшееся в возрасте 18 лет сразу после учений, было под руководством отца. У него были корабли и были свои люди для этих дел, и вот, спустя столько времени, он наконец-то стёр с них пыль уже при сыне. Это воспоминание Раймону наиболее дорого, ведь именно тогда отец сказал ему, что его мечта не может быть важнее семьи, но он не позволит ей умереть. Тогда Селио решил за все годы искупить свою вину этим путешествием, пусть и понимал, что чертовски рискует и своей собственной целью, амбициями. Но таков был приказ испанской короны. Вооруженная эскадра в лице галеонов отправлялась сопровождать торговые испанские корабли от нападений других корон во время перевозки ценных серебряных и золотых монет, а также различных товаров из Америки в Испанию. Отсутствовать отцу и сыну семьи Диас придётся целых 2 года, до 20-летия парня."}),(0,i.jsx)(s.p,{children:"Раймон светился от представившимся ему возможностям, он столкнулся с очень большим количеством людей, познакомился с новым обществом и даже завёл друзей среди взрослых дядек, что многому его научили за это первое плавание. За это время он очень много проводил времени с наёмниками и пиратами, перенимал их черты и поведение. Во многом Раймон не был похож на аристократа, да и вовсе не вспоминал о своей гордыне, довольствуясь окружающим воплощением его мечты. Команда во многом была дружна, руководитель из Серио был что надо во время плаваний, поэтому практически опасных ситуаций и не возникало, и Раймон впервые увидел своего отца совершенно с другой стороны… его глаза тоже светились, пусть и не по-детски, но дух свободы в нём ярко чувствовался. Вот, что называется… сын своего отца, рождённых морскими душами ещё со времён прадеда-покорителя."}),(0,i.jsx)(s.p,{children:"Как-то раз на кораблях была даже ситуация, когда ночью на них напали английские корабли. Это была незабываемая ночь для Раймона, ведь именно тогда он окончательно для себя решил, что хочет посвятить свою жизнь испанской короне и морскому делу. Это было их первое удачное отбитие атаки со стороны английских корсаров, стремящихся заполучить все бесценные товары, однако эскадра Серио не была столь слаба, обладала хорошо оснащенным флотом и сопровождала десятки торговых кораблей, поэтому всё обошлось относительно гладко."}),(0,i.jsx)(s.p,{children:"На протяжении этих двух лет они возвращались примерно раз в несколько месяцев домой, к своей семье, но не могли подолгу задерживаться на суше: Раймон с большой охотой встречался со своей горячо любимой сестрой, которой на тот момент исполнилось уже 13 лет. Как-то раз он попал даже на приезд 15-летнего Августа, и весьма удивился, когда заметил уже двоих взрослых подростков. На месяц им удалось задержаться всей семьёй и провести время, пока не настало время уплывать в очередной раз. Кажется, именно тогда Селио должен был пожалеть о своём решении, потому что именно с этой страницы истории начинается момент, когда Раймон сотрёт все границы между сушей и морем."}),(0,i.jsx)(s.p,{children:"По возвращении из долгого мореплавания (в течение 6 лет) маркиза уже вместе с сыном в 1565 году, маркиз Диас вновь приступил к своим делам. Временно он заслужил отпуск, как ему могло показаться, спустя столько лет плаваний с победами, поэтому предполагал, что на года 2 его точно оставят в покое. Это не радовало отца, но дало ему время на реорганизацию своих позиций внутри аристократии и повышения их важности. Кроме того, близился час, когда его дочь будет юной дебютанткой, а это значит, что наставал час искать ей нужную партию."}),(0,i.jsx)(s.p,{children:"Спустя годы обучений, а потом и плавания, Раймон впервые чувствует себя по возвращении как человек, который реализовал все свои мечты. Казалось, что больше ему не хотелось жить здесь, а вернуться исключительно туда, где он чувствовал энергию жизни, к чему тянулась душа. Однако теперь Раймону пора задуматься и о своём долге, как о сыне самого маркиза. Он ещё успеет вернуться в море, но положение обязывало утвердить себя в высшем обществе сильнее. Он начинает активно посещать балы, естественным образом, уже самостоятельно, и теперь встречается с именитым графом испанским - Полом Вагнером! Встреча двух товарищей ещё не раз будет пересекаться за всю жизнь этих людей, и в будущем они ещё успеют разделить судьбу двух мореплавателей. Но пока что - это их первая встреча после возвращения Раймона с официальной службы, на которой молодые люди активно обменивались происходящим друг с другом и информацией в принципе. Очень много времени первый год Раймон особенно уделял светскому обществу. И за всё своё время нахождения внутри него Диас уяснил только одно: это не его почва. Раймон отлично парировал и выходил из любых ситуаций, с энтузиазмом и пылкой чуткостью подходит в разговорах с темой о политике и обсуждении военного ремесла, наслаждаясь окружающим его интеллигентным обществом, и только к одному будущий маркиз не мог привыкнуть - к отношениям с женщинами. Он умудрялся покорять юных девушек своей харизмой, нередко приглашая некоторых из них на танец согласно этикету, дабы о нём не ходили почём зря разные слухи, но никогда не обменивался с ними душевными монологами, не посвящал им стихи и не пытался уединиться. Раймон не хотел понимать прелести отношений с ними, посему довольно часто пресекал любую попытку девушек надолго оставаться с ним, особенно наедине, тактично уходя от неловких ситуаций. Крайне редко молодой человек позволял себе оказаться наедине с такими, и лишь ради своей репутации."}),(0,i.jsx)(s.p,{children:"И, возможно, стоило бы маркизу Селио Диасу задуматься об этом, но сейчас он занимался более важным делом - искал подходящую партию для Раймона, чтобы связать с девушкой хорошего происхождения. Помолвка и бракосочетание с военными всегда дело было долгим и кропотливым для родословной Диасов, поэтому сейчас, имея хоть немного времени до начала нового призыва со стороны короны, он начал поднимать старые знакомства и родственников."}),(0,i.jsx)(s.p,{children:'Одна ситуация случилась в возрасте 22 лет Раймона. Тогда к ним вновь приехал Август и они проводили втроём довольно много времени, но кое-что Диас заподозрил. Как-то невзначай он заметил переменчивые взгляды этих подростков, особенно шаловливые искры Эриды. Скоро парень с большой неожиданностью для себя увидит, как его сестра и кузен занимаются непристойностями, выходящими за рамки уже "родственной" связи. Это разозлило Раймона, и он вмешался, прервав тех и прочитав нравоучения. Он не поднимал шума, но его голос был грубым и строгим. Недовольный поведением сестры и будучи злым на брата, Раймон недоумевал только одного: неужели они не понимали последствий от тех действий, которые совершали? Ещё бы чуть-чуть - и это было уже клеймом семьи Диасов. Он объяснял им это яростно долго, и почти настоял, чтобы Август сейчас же уехал и они прекратили всё это. Август действительно через несколько дней уехал, особенно после личного серьёзного разговора один на один.'}),(0,i.jsx)(s.p,{children:"Это был всё тот же 1567 год. Имя, ненавистное Раймону всей душой уже после смерти, а когда-то искренне любимое подобно лучам самого тёплого и ярчайшего солнца, ради которого Раймон выходил живым из самых, казалось, невозможных ситуаций… Когда-то в этом мире появилась юная дебютантка по имени Элизабет Нарлес. И пропустить дебют столь юной дочери графов он всё же не мог, поэтому был вынужден посетить приём. Причиной он выставил довольно крупное собрание высоких лиц, ибо всё-таки граф Нарлес был весьма именитым и имел широкие связи, чего Раймон в своём положении упускать не особо хотел. Однако вместо ожидаемого желания провести время со светскими людьми, он встретился с нежной и маленькой, хрупкой девушкой. Её бархатность и красота покорили Раймона, когда девушка согласилась танцевать с ним, и после этого он не мог оторвать больше взгляд. Даже Пол удивился, когда встретил отрешенного от таких вещей Диаса. Девушка тогда дала танец многим людям, но только Раймона она фанатично повлекла за собой. Диас тогда ничего не ответил своему другу, но и не подошёл больше к девушке."}),(0,i.jsx)(s.p,{children:"В этом же году прекрасной звезде маркизства Диас предстала возможность дебютировать в свои 15 лет. И Раймон, и Август приехали тогда на этот роскошный бал. Тогда Раймон стал главным сопровождающим дражайшей сестры, и именно с ним она станцевала свой первый танец. Далее - молодой человек практически не сводил взгляда с этой компании между Августом и Эридой… он знал об их отношениях. И не одобрял их, но решил скрывать от отца такие новости для их же блага. Он много наблюдал за ними, хотя и не позволял сестре оставаться наедине с кем-либо подолгу. На Августа он косился особенно осуждающе, но от этого его отношение к нему хуже не стало. Братья смогли поговорить и даже понять друг друга, но Раймон сразу же пригрозил, что никаких отношений у них не будет. Возможно, в будущем он пожалеет о своём выборе, но сейчас он искренне хотел действовать на благо чести семьи."}),(0,i.jsx)(s.p,{children:"На этом же дебюте Раймон столкнулся с Элизабет, с которой он вновь станцевал, но теперь они могли поговорить немного подольше. Раз за разом, на протяжении года они будут встречаться и возвышать сначала стену небольшой дружбы между молодым человеком и юной девушкой, а после - это перерастёт в пылкую и доселе неизвестную Раймону любовь, которую он будет ненавидеть больше всего в своей жизни. На протяжении всего года они будут сталкиваться и наслаждаться компанией друг друга, гулять совместно по саду или романтично поглядывать в сторону звёзд из тени больших деревьев. Страсть, что разгорается между двумя испанскими корнями, заставила их слиться в унисон: она искусила его и чуть не заставила совершить непоправимое в ту тихую ночь на одном из балов, настаивая на том, что его любовь должна подтвердиться на словах. Раймон заподозрил неладный смысл в этих словах, из-за чего отказался от подобного, как бы сильно не хотел. Диас не являлся особо верующим, но верил в традиции, из-за чего не позволил бы завести грязные отношения даже с возлюбленной всего сердца. Он настаивал, чтобы девушка подождала - и это очень обидело уже тогда 18-летнюю Элизабет."}),(0,i.jsx)(s.p,{children:'Спустя совсем не очень долгое время, как оказалось, меньше года хватило Эрнестине Диас, чтобы выбрать Эриде мужа и выдать её прочь из семьи - наверное, это в принципе самое первое появление матери в жизни как брата, так и сестры. Это сильно удивило Раймона и оторвало от души будто что-то важное. Хватило всего месяц уже в 24 года, чтобы заставить Диаса тосковать. Тем же часом отец начинает давить на него, и Раймон официально признаётся, что у него уже есть дама сердца и он заинтересован заключить брак. Маркиз Селио не очень одобрял пассию, выбранную парнем, но не стал возражать, ведь они всё равно не смогут спешить из-за своего "особенного положения" - скоро испанская корона вновь даст о себе знать.'}),(0,i.jsx)(s.p,{children:"Графство Нарлес и маркизство Диасов встретилось для обсуждения нюансов. Было принято решение подождать, когда Раймон вернётся из морского путешествия, когда всё тот же Филипп II стал собирать флотилию. Селио уже не мог вступить в эти боевые ряды, но этого безумно долго ждал уже сам Раймон. В каком-то смысле это станет для него даже глотком воздуха, ведь он впервые сможет получить лицензию корсара и опробует себя в этом ремесле самостоятельно."}),(0,i.jsx)(s.p,{children:"На прощание с ним встретилась возлюбленная Элизабет, и, казалось, вся её обида будто исчезла с её невинных глаз: неизвестно, чем она была очарована, но её таинственное предвкушение и нежный поцелуй на прощание, искренняя клятва и просьба с любовью в сердце вернуться… Раймон не сдержался и действительно дал эту клятву вечной любви, что, невзирая на любые трудности, она всегда будет его второй душой. Кулон, который подарила ему девушка, почему-то всегда был его слабым местом, но в будущем Диас поймёт, что этот кулон символизировал не вечную любовь юности, а последнюю их встречу."}),(0,i.jsx)(s.p,{children:"Только спустя год, в свои 25 лет, Раймон вернётся с чередой нескольких побед и освободится на ещё один год, но он ещё не знал, какое событие его ждало."}),(0,i.jsx)(h,{src:"/anketa-images/raymond-diaz/raymond-diaz-bio1.webp"}),(0,i.jsx)(s.p,{children:"Стоило только вернуться домой, мужчина сталкивается с ситуацией наследования титула. В его глазах была немного глупая или даже наивная надежда о том, что всё будет по-прежнему, но реальность громогласно вернула его на землю... Из-за смерти отца он автоматически становится маркизом, а о причинах смерти Селио уже новоставленный маркиз узнаёт непосредственно от своего друга Вагнера: оказывается, что Селио вызвал какого-то мужчину на дуэль и погиб. Когда он узнал о причинах подобного, это неистово обозлило Раймона и оставило в нём глубокую пустоту и обиду. Узнал маркиз Диас и об измене своей возлюбленной, ради которой он был готов свернуть горы и подарить небеса, но мечты разбились на осколки и заставили Раймона измениться навсегда."}),(0,i.jsx)(s.p,{children:'Первое, чему за этот год посвятил свою жизнь Раймон Диас - это месть, причём на законном основании согласно тому, что это был уже не просто дуэль каких-то людей, а убийством офицера и главы семейства, что автоматически объявляло войну двух семей. Раймон с большой радостью принялся восстанавливать честь своей семьи. В первую очередь оскорблённый изменой маркиз позволил себе жестокосердность, которую держал всегда подальше от суши, но проявил в отношении семьи любовника Элизабет Нарлес. Он без лишних промедлений, решив разве что срочные дела, бросил вызов любовнику на дуэль и погубил его. Сражаться на тот момент они приняли решение на шпагах, где Раймон, закалённый опытом, позволил себе не промедлить и без излишнего гуманизма лишить того жизни. Однако юный маркиз не планировал останавливаться только на этом мальчишке - в его интересах было уничтожить всю семью, естественно, по мужской линии. Ещё неоднократно Раймон Диас будет вызывать мужчин семейства Гонсалес и пользоваться своей чёрной удачей, которой никогда не стыдился, позволяя себе различные хитрости и уловки, чтобы выходить из битв живым. Раз за разом, вырезая чужое семейство, он испытывал всё большее презрение к своей бывшей возлюбленной, и хватило уже отомстить обидчикам, но это оставило рану на душе мечтательного молодого человека, оставшегося без самых важных членов своей семьи. В будущем её зашьет смерть Элизабет от его собственных рук, когда девушка будет самолично молить Раймона об убийстве, чтобы он сам взял на себя этот грех, ибо безмерно любила того, кого он убил. Это окончательно убило жалость и веру Раймона в человеческие чувства в принципе, на что он позволил себе совершить грех со словами "В отличие от тебя, маленькая мученица, твоё убийство не станет для меня ни грехом, ни наказанием" - Раймон не испытывал фееричной и фанатичной веры в католицизм из-за ужасов войны, а после этого и вовсе не считал совершенное чем-то плохим. В будущем кулон, подаренный Элизабет, Раймон будет хранить не как подарок от какой-то женщины, а память о своей маленькой наивности, от которой и в загробной жизни будет смеяться ещё не раз.'}),(0,i.jsx)(s.p,{children:"В 1570-м году Эрнестина Диас скончалась от болезни. Оставшийся одиноким маркиз больше не хотел выходить в светское общество: он отстоял честь своей семьи и больше не видел никакой необходимости в подобном, поэтому с радостью снова принял приглашение испанской короны на возвращение в море, отдавая ещё три года службе с особым энтузиазмом и жестокостью. Тогда с ним пойдёт путешествовать уже и сам Габриэль де Эстрада, присоединившись к флоту Диаса, и именно здесь граф спасёт ему жизнь и докажет Раймону, что ещё не всё потеряно. Так они и дали друг другу обещание обязательно вернуться живыми, однако же Эстрада погиб при отбитии атаки, поэтому больше они никогда не увидятся… и это разобьёт Раймона ещё сильнее, заставив в будущем надолго забыть о морских путешествиях, о которых его душа всегда будет глубоко внутри ныть, когда он будет смотреть на это море, закаты и корабли."}),(0,i.jsx)(s.p,{children:"Вернётся из этого изнурительного путешествия маркиз уже в свои 28 лет, в 1573 году. По возвращении он встретится с ненадолго остановившимся Августом и обсудят положение окружающих дел. Теперь, когда парень уже в возрасте 22-х лет, он будет навещать маркиза Диаса намного чаще, чем предполагалось, что создаёт в Раймоне дикие сомнения о том, что его хотят убрать с этого места. Впрочем, он их не выказывал, наблюдая за каждым действием кузена, но его, похоже, гложило кое-что совсем другое. Как узнал уже Раймон, подобно чистосердечному признаю, граф норвежский Линдберг рассказывает ему о своих отношениях с Эридой, что уже давно была замужней женщиной. Маркизу уже… и не было никакого дела до этой новости, даже если это относилось к чести его семьи: потеря и смерти близких ему людей так или иначе оставили свой след, как бы он не пытался этого скрыть. Раймон не одобрял, но и не отрицал их отношения, решив пустить всё на самотёк. На несколько месяцев маркиз выпал в осадок безразличия, больше не видя смысла жизни - ему предстоит долгий путь, чтобы обдумать всё случившееся за столько лет, принять это, как подобает, и найти новую цель."}),(0,i.jsx)(s.p,{children:"Впервые по возвращении Раймон слышит слухи о том, что его сестра больна, что заставляет маркиза настаивать на встрече со своей дражайшей сестрой и проводить с ней больше времени. Но, как оказалось, болезнь никакая не губила его сестру, и происходящее - это сущий бардак. Раймон убедился в этом, когда спустя несколько приездов услышал разговор сестры и её супруга, и он заметно отличался от того образа, которого они играли раньше перед публикой и теперь уже перед ним. Здесь что-то было нечисто, а частые приезды Августа в Испанию пробуждали в нём нехорошие догадки о ситуации. Это заставило маркиза взять себя в руки, и он начинает потихоньку восстанавливаться в обществе и чаще посещать различные мероприятия. Пришлось заново приспособиться, пришлось становиться жёстче. Теперь ничего не могло сомневать общество в том, что Раймон унаследовал потомственные черты и поведение старших маркизов семьи. Помимо этого, мужчина начал интересоваться политикой и военными подвигами, начал интересоваться бизнесом и экономикой, имел смелость инвестировать и поддерживать какие-то дела, способствуя поддержке аристократии и ведению различных связей за этот же счёт. В целях Раймона было желание обрести силу и власть для того, чтобы раздавить неугодных его семье - наверное, именно сейчас он понял, о чём всю жизнь твердил ему уже покойный маркиз Селио."}),(0,i.jsx)(s.p,{children:"В 1574-1575х годах Раймон активно предпринимает попытки разъединить сестру и её мужа, но старается это делать непринуждённо, чтобы граф поверил в свою значимость этой семье, к которой он когда-то присосался, как пиявка, ради денег. В таком случае, если хочет получить признание и стать ещё богаче, то Раймон начал вести с родственником дела и постарался как можно сильнее сблизиться. Свою раннюю непричастность он пояснял тем, что коротал службу в морях, посему у него практически и не было шанса попадать подолгу на землю для ведения настоящих дел. Тем же часом, он договорился с Августом, чтобы тот мог встречаться с Эридой, если представлялась возможность, чтобы помочь дорогой сестре отдохнуть. Как-то раз Август даже поделился с ним, что на руках женщины есть очень много неприглядных ран для дочери маркизного дома, что заставило Раймона не просто выдёргивать того из дома, а искать и его слабости для того, чтобы сломать в одно мгновение, отомстив. За это время маркиз особенно изощрялся, проявлял смекалку и изобретательность."}),(0,i.jsx)(s.p,{children:'Благодаря своим умениям к 1579 году маркиз умудрился очень замысловато подставить наивного графа Амадо Ледесме и обанкротил. В этот год Раймон и Август решили провести "спасательную кампанию" для своей бедной сестры спустя годы мучений, и теперь ловушка замкнулась и поймала зайца. Раймон приглашает погостить у себя Амадо и Эриду под предлогом того, что все вопросы они смогут решить, нужно оставаться спокойными, заговаривая зубы графу о недоброжелателях. К этому же моменту, совсем уж поздно ночью, Август позаботился о том, чтобы имения графа были сожжены, в то время как Раймон напоил того подобием снотворного. Сестра о планах не знала буквально до тех пор, пока маркиз Диас не запер мужчину в подвале своего поместья и не устроил комнату допросов, которые в будущем превратятся в уже комнату пыток по совместительству всех трёх людей, мстящих за грязное отношение. Однако свою форму мести он продемонстрировал последним штрихом, когда от графа ничего не оставалось живого - и он сжёг его заживо, не позволяя тому издать и писка. Благодаря произошедшему Эрида смогла вернуться домой и оставаться у своего старшего брата ещё надолго, и разлетелись слухи о том, что граф погиб из-за невозможности спастись в самом пожаре. Погибло также большое количество слуг, а те, кто выжили, были подкуплены и не говорили о причастности кого-либо в принципе. Однако в дом Раймону пришлось принять ещё и сына Эриды, хотя, если честно, он жалел о том, что не убил его. Раймон и Август относились к мальчику с некоторой неприязнью и жёстко контролировали каждый шаг.'}),(0,i.jsx)(s.p,{children:"Пока Август решал дела насущие, Эрида пожила в доме своего брата как вдова ещё два года, он же - всё также продолжал наращивать свою мощь, особенно в последние годы акцентируя внимание на флотилии и наёмниках. Лишь к 36 годам он повторно наблюдает замужество своей любимой сестры, но, видя её искреннее счастье и радость, маркиз только сейчас мог отпустить её с чистым сердцем. Кузен, теперь уже официальный супруг, забирает Эриду и её сына в Норвегию, откуда он неоднократно будет получать письма о благосостоятельной жизни. Будучи уверенным в счастье своих родственников, о своём собственном теперь он мог и вовсе позабыть, ведь он исполнил как свой долг, как наследника этой семьи, так и честь искупил. Наверное единственное, что из этого списка он не хотел выполнять - это иметь своих детей, однако Раймона это нисколько не беспокоило. Потому что он снова отправится бороздить просторы, но теперь уже со спокойным духом и верой в то, что его больше ничего не держит на суше."}),(0,i.jsx)(s.p,{children:"На протяжении всех этих лет Раймон то и дело путешествует. Он наслаждается проведённым временем и свободой, ведь теперь сам его дух не чувствовал на себе оков. За эти годы Диас познакомился с огромным количеством людей, находил настоящий врагов и соперников, пусть и не с таким энтузиазмом, как в свои более юные годы. Участвовал в боевых сражениях, даже в немилость погоды попадал. Начал активно играть в азартные игры и наслаждаться последними годами - ведь только море было утешением."}),(0,i.jsx)(s.p,{children:'Однако конец блудной души, встретившей величие и падение в то же время, выдалось на промежуток между 1585-1588 годами, когда Раймон сталкивается с эскадрой Френсиса Дрейка - именитого английского пирата, подвиги и злодеяния против Испании которого пробуждают в нём неистовый вкус сражений. Неоднократно флотилии их сталкивались, но наиболее запомнившееся и открытое сражение именовалось "Непобедимой армадой" под руководством герцога Медина-Сидонии. Он был выдающимся адмиралом, под флагманом которого маркиз был готов отправиться в путь. Диасу пришлось приехать в один из портов Португалии для сборов - в лиссабонскую гавань. После того, как были улажены вопросы с провизией и моряки восстановились, по приказу короны они были вынуждены выдвинуться в атаку, где их в Ла-Манше уже поджидал английский флот.'}),(0,i.jsx)(s.p,{children:"Учитывая бо́льшую манёвренность и артиллерийскую мощь английского флота, испанский адмирал для лучшей защиты расположил свой флот полумесяцем, поставив по краям самые сильные военные корабли с дальнобойной артиллерией. Кроме того, ближе к противнику он выставил «авангард» (фактически арьергард) из самых лучших кораблей. С какой бы стороны ни подошёл противник, этот отряд мог развернуться и отразить атаку. От остального флота требовалось держать строй и не терять взаимной поддержки, чего и Раймон придерживался. Пользуясь преимуществом в манёвренности, англичане с самого начала вышли Армаде на ветер. С этой выгодной позиции они могли атаковать или уклоняться по желанию. При преобладавших западных ветрах это означало, что они преследовали Армаду по мере её движения Ла-Маншем, беспокоя её атаками. Однако разорвать оборонительный порядок испанцев долго не удавалось."}),(0,i.jsx)(s.p,{children:"Первое время успех был на стороне испанского флота. Занятая испанцами оборонительная позиция оправдала себя: англичанам с помощью дальнобойного оружия так и не удалось потопить ни одного испанского корабля на протяжении всех небольших летних стычек. Английские капитаны решили во что бы то ни стало нарушить боевой порядок врага и приблизиться к нему на расстояние выстрела. Это им удалось только 7 августа при Кале, где Раймон и встретил свою смерть. Воспользовавшись уязвимым положением стоявших на якоре испанских кораблей по приказу герцога, англичане ночью направили к Армаде восемь брандеров — подожжённых судов с горючими материалами и взрывчаткой. Большинство испанских капитанов рубили якоря и лихорадочно пытались уйти от опасности, но маркиз решил этого не делать - взрыв не состоялся. Лишившись якорей, испанская эскадра уже не могли сохранять боевой порядок у Кале, и строй распался, что сильно ударило по положению флотилии."}),(0,i.jsx)(s.p,{children:"Утром, 8 августа, начав нападение, англичане по-прежнему избегали абордажных схваток, обстреливая противника, но теперь уже на близкой дистанции, где их пушки причиняли испанским кораблям значительные разрушения, и сосредоточив огонь на отдельных, оторвавшихся от строя кораблях. Канонада продолжалась около девяти часов, буквально на истощение. Испанские суда, менее маневренные, из-за противного ветра не могли оказать помощи друг другу, из-за чего один из потопленных кораблей, что просто не успевали откачивать воду, оказался затоплен. Возможно, Раймон смог бы выжить и вернуться домой, однако ранение с предыдущих столкновений дало о себе знать, из-за чего испанский капитан просто утонул, не способный всплыть из-за сильного течения."}),(0,i.jsx)(s.p,{children:"Это была отчаянная борьба за жизнь, но лишь под конец Раймон сдался, так как понимал, что с самого начала эта битва не имела никакого смысла: очень многие испанские капитаны и ранее были взволнованы предстоящим сражением, однако испанская корона и слушать ничего не хотела. Неизвестно точно, сожалел ли Раймон о своей смерти именно под таким углом, но то, что он вспомнил самые ранимые для него моменты, не способный оставаться в сознании, врезалось у него в память навсегда."}),(0,i.jsx)(s.p,{children:"И только рядом плавающий с ним крест тонул вместе с телом ещё живого морского духа, сопровождая в последний путь, — на свободу."}),(0,i.jsx)(h,{src:"/anketa-images/raymond-diaz/raymond-diaz-bio2.webp"})]})}),(0,i.jsx)(r,{title:"Жизнь в Энкраже",children:(0,i.jsxs)(x,{children:[(0,i.jsx)(s.p,{children:'Первое появление Раймона в Энкраже предстаёт в полном недоумении в отношении нового места, куда он попал, но его изрядно начинают мучать воспоминания, о которых он не успел забыть из-за своей сильной ментальной связи с ними. Кроме того, прохождение башни происходило весьма "феноменальным" образом, ведь воспоминания не просто сводили его с ума, но и не давали ему здраво мыслить, бросая то в одно течение истории, то в совершенно другое. Вполне вероятно, что Раймон так и затерялся в собственных воспоминаниях и сошёл с ума, если бы на одном из этажей не нашёл тот самый крест, который утонул вместе с ним. Он имел весомое значение для жизни мужчины, из-за чего это позволило вырваться ему из лап того неистового сумасшествия и справиться со своим первым испытанием.'}),(0,i.jsx)(s.p,{children:"В Энкраже Раймон приспосабливался не очень долгое время, хотя и был угнетён тем фактором, что больше не сможет услышать шум морского прибоя, ибо от моря здесь остались буквально капли, которых, как поговаривали сначала, нельзя было касаться. В этом мире, получив своё лисье обличье по ощущению, Раймон принялся изучать информацию по поводу окружающего его места, дабы как можно быстрее к нему приспособиться. На тот момент он вычеркнул очень много известной на тот момент грешникам информации. Хотя, кажется, читать книги станет самой основной привычкой Диаса, так как знания обладают неимоверной силой особенно в столь юные годы. Тем же часом он открыл в себе способности управления различными иллюзиями, которые тут же вдохновили его на различные идеи и возможности. Можно сказать, что в них мужчина видел спасение, пусть поначалу природа магии и не была ему слишком ясна: сначала он пробовал маленькие иллюзии реализовать внутри замка, но ради масштабных чаще всего уходил из замка, недалеко в лес, и пытался расширить границы не только своего сознательного понимания, но и уровня самой способности. В будущем Раймон будет практически ежедневно практиковать её, что позволит ему раскрыть полный потенциал своих загадочных и новых сил."}),(0,i.jsx)(s.p,{children:"Примерно в возрасте около 6 лет Раймон сталкивается со своей сестрой Эридой в Энкраже. Явление любимого члена семьи стала усладой в жизни бывшего маркиза и успокоила его, а мир вечности позволил наверстать упущенное время, пока тот воевал. Теперь уже ногицунэ не разделялись друг от друга, постоянно держась вместе, практически везде. Ещё через 9 лет, когда в Энкраже он уже будет 15, Раймон встретит своего брата Августа и поможет ему вспомнить всё необходимое, благодаря чему семья, но теперь уже, что забавно, лисов, соберётся вместе. Наверное, Раймон ещё никогда не был счастлив тренироваться со своими родственниками и делиться с ними различными знаниями без фактических ограничений, что поселило в нём умиротворение."}),(0,i.jsx)(s.p,{children:"В свои 30 лет Диас впервые познакомится с тем, кому в будущем будет готов стать верным товарищем и служить верой и правдой - Мораном. Тогда он не появлялся часто и завоевать его доверие было чертовски непросто, однако единожды проведённый между ними спарринг изменил мнение обоих. Шрам на лбу как раз мужчина получил во время сражения, когда не рассчитал силы и подобрал весьма неудачный момент для атаки. Как Раймон говорил сам, ему казалось, что он был довольно близок к тому, чтобы лишиться головы, но благодаря своевременной реакции и толики удачи смог избежать более серьёзных последствий. Впрочем, у Диаса был интерес присоединиться к нему, ибо казалось, что история у них весьма похожа, да и родное что-то в этом грешнике однозначно есть. Виделись они нечасто вплоть до 84-летия ногицунэ, когда у него уже присутствовал 2-й хвост на своём веку. Тем не менее, это помогло развить им повсеместное сотрудничество, в то время как Раймон успел доказать свою непосредственную верность, следовало ему только узнать об идеологии и цели Морана. Познакомившись с его целью, Раймон стал первым, кто поверил в Морана и последовал за ним с самого начала. На него смотрели как на безумца, а Раймон видел в мужчине лишь цель и бесконечную веру, о которой грезил когда-то сам. Это ужасно зацепило лиса. После этого они стали будто неразлей вода, а когда Моран перестал исчезать без причин и уже на постоянной основе открыто ходил, то он и своих родственников познакомил с тем, кому готов был посвятить свою карьеру. Он вошёл во вкус и был доволен своей новой компанией, а после этого присоединился и к его организации - Ордену, помогая непосредственно в её дальнейшем развитии."}),(0,i.jsx)(s.p,{children:"Благодаря дальнейшему развитию Ордена, где Диас проведёт большую часть своей жизни в развитии и устоявшейся цели, он сможет добиться небывалых высот в изучении собственных навыков, а потом начнёт приносить и свой собственный маленький вклад в изучение окружающего мира, хоть весьма и своими методами, что как-то раз и вовсе привело к тому, что Раймон стал одним из немногих грешников, который смог изучить Пустого и не получить наказание. Более того, он продолжает заниматься их изучением в своей собственной лаборатории. Отдельно хочется сказать о том, что у него есть дневник, в котором он детально описывает полный разбор пустых, начиная от тела и заканчивая попыткой изучить духовное. В этой же организации он знакомится с Анжелией Вайтгрейв, где впервые узнал о своей неприязни к женщинам. Впрочем, спустя огромное количество времени им пришлось сблизиться, ибо девушка испытывала особенно яркий интерес в изучении многих вещей и готова была развивать их и саму себя."}),(0,i.jsx)(s.p,{children:"В течение всей своей жизни Раймон только и мог, что заводить интересные знакомства и искать нечто новое, но он, подобно тому, кто хотел стать правой рукой Морана, старался делать практически всё, что тот его попросит, что символизировало о его некоторой верности. Однако одна из таких просьб… в общей степени повлияла на то, что Раймону пришлось очень долго мучиться с ещё одной женщиной - Эстер Клеман, - которую он должен был обучить по требованию Морана и стать наставником. Это были самые мучительные года привычки мужчины, но, со временем, он выработал свою терпимость и смог раскрыть потенциал лисицы ещё больше, в то время как на своём веку уже давно получил титул одного из лучших иллюзионистов своего времени."}),(0,i.jsx)(s.p,{children:"Совсем недавно, буквально лет 30 назад, Раймон стал девятихвостым ногицунэ и получил дар бесконечного видения, которое развивает с особым энтузиазмом, однако из-за него Раймону пришлось начать носить специальный магический артефакт, который скрывает его переменчивый взор и способности. Он и в более ранние годы делал это, но это был обычный кусок ткани до тех пор, пока не потребовался некоторый сдерживающий предмет."})]})})]}),(0,i.jsxs)(r,{title:"Дополнительно",children:[(0,i.jsx)(h,{src:"/anketa-images/raymond-diaz/raymond-diaz-facts1.webp"}),(0,i.jsxs)(r,{title:"Факты о персонаже",children:[(0,i.jsx)(h,{src:"/anketa-images/raymond-diaz/raymond-diaz-facts.webp"}),(0,i.jsxs)(c,{children:[(0,i.jsx)(j,{title:"Сексуальная ориентация",children:(0,i.jsx)(s.p,{children:"Раймон является гетеросексуалом, однако из-за травмы в жизни отрицает любые сексуальные/романтические отношения."})}),(0,i.jsx)(j,{title:"Погружение в прошлое",children:(0,i.jsx)(s.p,{children:"Раймон при свободной минутке любит окунуться в прошлое. Чаще всего он либо закрывает глаза и смотрит на воображаемые вещи, либо, если желает видеть и ощущать всё воочию, погружает себя в иллюзию самозабвения."})}),(0,i.jsx)(j,{title:"Популярность",children:(0,i.jsx)(s.p,{children:"Грешник обладает популярностью среди тех, кто умело пользуется магией иллюзий — даже среди талантливых кицунэ и сикигами Раймон является тем, к кому обращаются за советами. Возможно, всё дело в особенных глазах, раскрывших не так давно суть бытия."})}),(0,i.jsx)(j,{title:"Покер",children:(0,i.jsx)(s.p,{children:"Выигрывает в покер у Морана. У грешников колоссальный опыт игры в карты, поэтому они часто соревнуются между собой. Пока что Раймон был единственным, кто смог несколько раз победить Морана, однако это не происходит так часто, как хотелось бы: победы зачастую периодические, из-за чего у змея и лиса обычно выходит ничья."})}),(0,i.jsx)(j,{title:"Отношение к женщинам",children:(0,i.jsx)(s.p,{children:"Раймон относится к девушкам скорее с дополнительной осторожностью и чуткой бдительностью, а также особенно ненавидит, когда к нему касаются незнакомые женщины. Ранимое прошлое заставляет Раймона опасаться ненужных ему связей с противоположным полом, даже если они и в теории не предполагают развития: любое касание и присутствие в целом очень напрягает его, и лишь для особенных он готов перешагнуть себя."})}),(0,i.jsx)(j,{title:"Повязка на глазах",children:(0,i.jsx)(s.p,{children:"Повязка на глаза скрывает половину его шрама на лице. Ещё бывают случаи, когда некоторые грешники отмечают, что видят глаза Раймона сквозь повязку когда он особенно зол."})}),(0,i.jsx)(j,{title:"Потеря пигментации",children:(0,i.jsx)(s.p,{children:"Однажды из-за слишком сильной концентрации и огромного количества поглощённой проклятой энергии Раймон утерял свою внешнюю пигментацию в образе цвета волос и глаз, немного видоизменив очень малую часть ЭПФО, но, что примечательно, как лис он сохраняет свою чёрную шерсть. Случилось это в особо сильный пик проявления его сил."})})]})]}),(0,i.jsxs)(r,{title:"Внешность",children:[(0,i.jsx)(h,{src:"/anketa-images/raymond-diaz/raymond-diaz-view.webp"}),(0,i.jsxs)(x,{children:[(0,i.jsx)(s.p,{children:"Самый что ни на есть лукавый и хитрый лис, но которому хочется доверять во многих случаях жизни: он источает уверенность, благородство и аристократичность — глядя на него, сразу поймёшь из каких он приблизительно эпох. Его спокойствие способно заставить сдаться и смириться, а учтивость и внимание создаёт из него поистине того принца из сказок, о котором многие девочки мечтали перед сном. В Энкраже Раймон даже не изменился, если исключить тот факт, что он стал куда более мужественнее и помолодел на пару лет."}),(0,i.jsx)(s.p,{children:"Из общих данных можно выделить достаточно высокий рост — 185м, в то время как вес составляет 74кг. Телосложение спортивное, до атлетического не дотягивает в силу того, что Раймон не особо заинтересован в настолько интенсивных тренировках, а предпочитает заниматься изучением чего-либо. Впрочем, ему постоянно приходится быть в движении и нередко попадать в бой, из-за чего форму приходится всё же поддерживать. Бледного цвета кожа."}),(0,i.jsx)(s.p,{children:"У лиса светлые волосы пепельного цвета, однако под ярким освещением может показаться, что их края слегка отсвечивают белым. Это происходит не просто так, а выявляет его некоторую причастность к расе: лишившись возможности призывать хвосты и уши, кончики волос Раймона окрасились в белый. Особенно это стало заметно тогда, когда лис достиг «просвещения», то есть получил свой последний хвост — удивительное везение, решившее проявиться именно подобным образом. Хотя натурально волосы у него чёрного цвета, таковы они исключительно у корней и виска, часто взъерошены и редко лежат ровно, что, очевидно, выбивается из его образа, но придаёт шарма."}),(0,i.jsx)(s.p,{children:"Форма глаз у него лисья, что подчёркивает не только его характерные черты, но и выдаваемый образ — он изучает, наблюдает, оценивает и подмечает. Ему нередко говорят при общении, что он задумывает нечто неладное, хотя в сущности может вообще ни о чём не думать. Есть кошачьи зрачки; цвет настоящих глаз Раймона — белый, однако из-за способности «Бесконечного видения» его глаза окрашены в королевский пурпур (при активной фазе)."}),(0,i.jsx)(s.p,{children:"Раймон отдаёт предпочтение официальному стилю 1900х, распространённому особенно в Лондоне: чёрный длинный плащ, чёрный пиджак с небольшим вырезом, белая рубашка с высоким воротником, чёрный галстук и брюки с заутюженными складками и скрытой застёжкой, чёрные туфли-оксфорды. Первоначально, при попадании в Энкраж Раймон старался соблюдать временные рамки в вопросах одежды, что соответствовали его стране, однако ближе к 20 веку Раймон остановился на конкретной старой (по нынешним меркам) моде просто потому, что не уважает более позднюю. Ухоженный, деликатный и строгий стиль с элементами минимализма."}),(0,i.jsx)(s.p,{children:"Отдельно хочется отметить особую любовь лиса к ношению перчаток в силу его острой фобии — без них Раймон чувствует себя как без рук, из-за чего в первую очередь на нём должны оказаться перчатки, а потом уже всё остальное. На глазах Раймона также присутствует артефакт в виде тёмной ткани, окутывающий его глаза и затылок, и благодаря нему Раймон способен не перенапрягать глаза при использовании способности девятихвостого лиса. Благодаря маске он может видеть грешников с очень слабым помутнением, но грешники не видят его глаз."})]})]}),(0,i.jsx)(r,{title:"Навыки и умения",children:(0,i.jsxs)(c,{children:[(0,i.jsx)(j,{title:"Ловкость рук",children:(0,i.jsx)(s.p,{children:'Раймон всегда жил в достатке и у него хватало денег, однако в море, порой из-за некоторой скуки, чтобы хоть как-то развлекать своих товарищей, показывал им различные действия с картами. Так это и переросло в заинтересованность Раймона сделать что-то уж слишком "незаметно", из-за чего ему открываются очень перспективные шансы научиться не только шулерству, но и даже воровать в прямом смысле этого слова. Однако ни первое, ни второе ему не близко, из-за чего ловкость рук можно отнести к "умению ради забавы".'})}),(0,i.jsx)(j,{title:"Единоборства",children:(0,i.jsx)(s.p,{children:"Раймон знает, как защитить себя от противника без магии, если к нему подойти на достаточно близкое расстояние. Даже если он не имеет оружия, он имеет достаточно силы, чтобы повалить противника, отскочить от него или обезвредить. Как минимум этому способствует то, что у ногицунэ хорошая ловкость и скорость. Помимо всего прочего, Раймон вынослив."})}),(0,i.jsx)(j,{title:"Азартные игры",children:(0,i.jsx)(s.p,{children:"Любовь и уважение. Раймон промышляет этим столько, сколько себя помнит: в карты он ещё на кораблях играх, пусть это и запрещалось, но конкретно на фрегате это не наказывалось, скорее даже подшучивали. Очень умел во многих карточных играх и даже способен в шахмоты, но он их не очень любит."})}),(0,i.jsx)(j,{title:"Игра на скрипке",children:(0,i.jsx)(s.p,{children:"Учился в Энкраже, когда впервые услышал звук этого мелодичного инструмента. Благо пальцы у него были длинные, а слух ныне тонкий. Первое время это было максимально противно, но и здесь нет ничего невозможного. Иногда поигрывает на скрипке от скуки."})}),(0,i.jsx)(j,{title:"Картография",children:(0,i.jsx)(s.p,{children:"Умение ориентироваться в картах и указывать правильное направление движение оказалось одним из необходимых дел при жизни корсара. Да и в целом благодаря этому хорошо ориентируется на местности и никогда не запутается в сторонах света. Отсюда и хорошая визуальная память."})}),(0,i.jsx)(j,{title:"Морские узлы",children:(0,i.jsx)(s.p,{children:"Вязание морских узлов."})}),(0,i.jsx)(j,{title:"Огнестрельное оружие",children:(0,i.jsx)(s.p,{children:"Хорошо обращается с мушкетным огнестрелом."})}),(0,i.jsx)(j,{title:"Математический склад ума",children:(0,i.jsx)(s.p,{children:"Математический склад ума, позволяющий мужчине какое-то время углубиться в основы экономики и, следовательно, неплохо поладить с числами. Хорош в аналитике."})})]})}),(0,i.jsx)(r,{title:"Слабости",children:(0,i.jsxs)(c,{children:[(0,i.jsx)(j,{title:"Потребность в подпитке эмоциями",children:(0,i.jsx)(s.p,{children:"Ногицунэ нуждаются в постоянной подпитке чужой злостью, ненавистью и прочими негативными эмоциями. Если происходит истощение, то их силы слабеют, а сами они становятся крайне раздражительными и теряют возможность контролировать себя. Чаще всего, если у Раймона нет никакой сторонней подпитки подобной энергией, у него начинаются сильные головные боли и тот становится более грубым, жёстким и агрессивным."})}),(0,i.jsx)(j,{title:"Чувствительность к энергии",children:(0,i.jsx)(s.p,{children:"Помимо того, что Раймон часто нуждается в подпитке чистой энергией, проблема его слабости заключается в других грешниках: он крайне чувствителен к любой энергии чужих для него грешников. По этой причине он крайне ненавидит скопления и особенно открытые бои с демонстрацией силы, боясь касания грязной энергии. Слабость пришла с тем, когда Раймон открыл в себе силы ногицунэ, поэтому любые прикосновения и магия, непривычная ему (а привыкает он очень долго) воспринимается довольно агрессивно и грубо."})}),(0,i.jsx)(j,{title:"Уязвимость к серебру",children:(0,i.jsx)(s.p,{children:"Кицунэ особенно боятся серебряного оружия, как и оборотни, из-за чего стараются остерегаться оппонента, у которого есть что-либо из данного материала в любом виде."})}),(0,i.jsx)(j,{title:"Резкие и громкие звуки",children:(0,i.jsx)(s.p,{children:"Как и любой зверь, кицунэ боятся резких и громких звуков, которые дезориентируют их, ровно как и высокочастотные звуки. Невзирая на то, что у Раймона нет ушей в человеческом облике, его слух ничуть не слабее настоящего, из-за чего высокие звуки сильно бьют по голове."})}),(0,i.jsx)(j,{title:"Растрата энергии",children:(0,i.jsx)(s.p,{children:"И хотя Раймон может использовать магию вне карт, если застать ногицунэ врасплох и вынудить использовать магию классическим способом, то он быстро растратит энергию и вся выносливость сведётся на нет. В остальном же порядке ослабить лиса будет довольно трудно, так как активация карты не занимает много времени и сил."})}),(0,i.jsx)(j,{title:"Ближний бой",children:(0,i.jsx)(s.p,{children:"Ближний бой требует отдельного упоминания. По существу, Раймон может вступить в ближний бой и даже неплохо держаться как боец ближнего боя. Конечно, конкуренцию тем, кто занимается этими вещами профильно более 200+ лет он составить, увы, не сможет полноценно, но вполне окажется неплохим соперником. Однако он старается всегда держать расстояние, панически избегая ближнего боя, если без него можно обойтись. Это — его крайняя граница: Раймон страшится испачкаться или получить ранение от грязной энергии, поэтому не полагается на свои силы в ближнем бою, хоть и имеет к ним хороший потенциал. Слабость игнорируется в случае, если Раймон: находится в опасности; сражается в полную силу с соперником, чья энергия ему не противна. Терпимее относится к сражению с противниками, если находится в перчатках, но даже так ему очень некомфортно менять свой стиль боя."})}),(0,i.jsx)(j,{title:"Уязвимость глаз с Бесконечным видением",children:(0,i.jsx)(s.p,{children:"У фиолетовых глаз со способностью бесконечного видения довольно много преимуществ, но и немало рисков: если ранить сей глаз при его активной фазе, то Раймон моментально лишится всех своих внутренних сил (но карты будут рабочими), сильно выведет его из строя и отключит пассивную работу способности глаз ногицунэ. Помимо этого, если перегрузить их большим количеством получаемой информации в течение 4 постов, то персонаж может и вовсе временно лишиться зрения (на 10 постов). Стоит отметить, что маска на глазах не имеет защиты: хоть она и не повреждается, но при получении урона в глаза - этот урон не отразится и пройдёт сквозь маску."})}),(0,i.jsx)(j,{title:"Перегрузка ядра",children:(0,i.jsx)(s.p,{children:"Из-за того, что ядро Раймона менее уязвимо ко внешнему миру, тем не менее, при сильном насыщении и использовании своей способности поглощения энергии он может нанести колоссальный вред собственному сознанию (происходит смена мировоззрения на Хаотичное Злое и абсолютно рандомное) и оболочке. Во время них лис мало того, что не контролирует себя и может навредить себе, так и просто с трудом восстанавливается. Помимо всего прочего, оболочка постепенно может начать растворяться на глазах, а Раймон даже не заметит. При очень сильно повреждённом сознании может довести себя до полной потери оболочки и остаться безумным навсегда."})}),(0,i.jsx)(j,{title:"Уязвимость к стихийной магии",children:(0,i.jsx)(s.p,{children:"Раймон крайне не любит сталкиваться с грешниками, у которых стихийная магия развита на уровне, способном конкурировать его иллюзиям. В основном это связано с грешниками, которые владеют магией льда, воды, огня. Если использовать подобного рода способности на его картах, есть довольно большой шанс того, что они просто повредятся, произойдёт утечка магической энергии и более использовать карту до полного отката масти не выйдет."})})]})}),(0,i.jsx)(r,{title:"Связанные персонажи",children:(0,i.jsxs)(c,{children:[(0,i.jsx)(j,{title:"Габриэль де Эстрада",children:(0,i.jsx)(s.p,{children:"Людской мир. Связаны крестом, подаренным при службе на кораблях. Это была клятва лучших друзей, когда-то вместе учившихся и даже чуть не погибших."})}),(0,i.jsx)(j,{title:"Элизабет Нарлес",children:(0,i.jsx)(s.p,{children:"Людской мир. Связаны кулоном, подаренным при клятве в вечной любви перед тем, как Раймон отправился в плавание."})})]})})]}),(0,i.jsx)(h,{src:"/anketa-images/raymond-diaz/raymond-diaz-main.webp"}),(0,i.jsxs)(t,{children:[(0,i.jsx)(s.p,{children:"Но я бедняк, и у меня лишь грёзы,"}),(0,i.jsx)(s.p,{children:"Я простираю грёзы под ноги тебе,"}),(0,i.jsx)(s.p,{children:"Ступай легко, мои ты топчешь грёзы..."})]})]})}function n(e,i){throw Error("Expected "+(i?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}e.s(["default",0,function(e={}){let{wrapper:n}={...(0,l.useMDXComponents)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(s,{...e})}):s(e)}])}]);